    if (!ptr) {
      throw new Error("failed to allocate a guest stack");
    }
    sp.value = ptr + WORKER_STACK_BYTES;
    if (tlsSize) {
      ex.__wasm_init_tls(Math.ceil((ptr + WORKER_STACK_BYTES) / tlsAlign) * tlsAlign);
    }
    if (typeof ex.__runtime_init === "function") {
      ex.__runtime_init();
    }
